_guards={
 'mg1':'p[0]<0||p[1]<=0||p[2]<0||p[0]*p[1]>=1',
 'erlang':'p[0]<0||p[1]<=0||!Number.isInteger(p[2])||p[2]<1||p[0]>=p[1]*p[2]||p[3]<0',
 'mixingtv':'p[0]<0||p[0]>1||p[1]<0||p[1]>1||p[0]+p[1]===0||p[2]<0||p[2]>1||p[3]<0||!Number.isInteger(p[3])',
 'ar1ess':'p[0]<1||!Number.isInteger(p[0])||Math.abs(p[1])>=1',
 'ei':'p[1]<=0',
 'gpclass':'p[1]<0',
 'gpkernel':'p[1]<=0||p[2]<0||![0,1,2].includes(p[4])',
 'squarednormal':'p[1]<0||![0,1].includes(p[2])',
 'bridge':'p[0]<0||p[1]<0||p[2]<=0||p[1]>p[2]'
}
