op('skewtwo','P Low High','Skewness','[(()=>{const m=p[0]*p[1]+(1-p[0])*p[2],v=p[0]*(p[1]-m)**2+(1-p[0])*(p[2]-m)**2;return (p[0]*(p[1]-m)**3+(1-p[0])*(p[2]-m)**3)/Math.pow(v,1.5);})()]',lambda p:[(p[0]*(p[1]-(p[0]*p[1]+(1-p[0])*p[2]))**3+(1-p[0])*(p[2]-(p[0]*p[1]+(1-p[0])*p[2]))**3)/(p[0]*(p[1]-(p[0]*p[1]+(1-p[0])*p[2]))**2+(1-p[0])*(p[2]-(p[0]*p[1]+(1-p[0])*p[2]))**2)**1.5],'A toy noise takes Low {Low} with probability {P}, otherwise High {High}. What standardized third central moment results?','Asymmetry is one departure from Gaussian noise. This moment alone does not identify a causal graph or verify the other assumptions of a discovery method.','grid')
