op('finitebranch','Zero Two Generations','Extinct','[(()=>{let q=0;for(let i=0;i<p[2];i++)q=p[0]+(1-p[0]-p[1])*q+p[1]*q*q;return q;})()]',lambda p:[_finitebranch(p)],'One toy lineage has 0 offspring with probability {Zero}, 2 with {Two}, otherwise 1. What is extinction probability by {Generations} generations?','Iterating the offspring generating function gives finite-generation extinction. This differs from its eventual fixed point.','grid')
def _finitebranch(p):
 q=0
 for _ in range(int(p[2])):q=p[0]+(1-p[0]-p[1])*q+p[1]*q*q
 return q
