op('voronoiline','SeedA SeedB','Boundary','[(p[0]+p[1])/2]',lambda p:[(p[0]+p[1])/2],'Two toy seeds lie at {SeedA},{SeedB} on a line with ordinary distance. Where is their equal-distance Voronoi boundary?','The perpendicular-bisector idea reduces to a midpoint on this line. A full plane partition needs all seed locations and a distance metric.','grid')
def hitbarrier(p):
 states={0:1.0};hit=0
 for _ in range(int(p[0])):
  nxt={}
  for x,w in states.items():
   for y,weight in [(x+1,w*p[2]),(x-1,w*(1-p[2]))]:
    if y>=p[1]:hit+=weight
    else:nxt[y]=nxt.get(y,0)+weight
  states=nxt
 return [hit]
op('hitbarrier','Steps Barrier P','Hit','[(()=>{let states=new Map([[0,1]]),hit=0;for(let i=0;i<p[0];i++){const next=new Map();for(const [x,w] of states)for(const [y,weight] of [[x+1,w*p[2]],[x-1,w*(1-p[2])]]){if(y>=p[1])hit+=weight;else next.set(y,(next.get(y)||0)+weight);}states=next;}return hit;})()]',hitbarrier,'A toy ±1 walk starts at zero, steps up with probability {P}. What is probability of first reaching positive Barrier {Barrier} within {Steps} steps?','Absorbing the first-hit mass answers a path event, not just endpoint position. This finite lattice model is not an exact Brownian first-passage distribution.','grid')
op('allcoupons','Types Draws','Complete','[(()=>{let sum=0,c=1;for(let k=0;k<=p[0];k++){if(k>0)c=c*(p[0]-k+1)/k;sum+=(k%2?-1:1)*c*Math.pow(1-k/p[0],p[1]);}return Math.max(0,Math.min(1,sum));})()]',lambda p:[max(0,min(1,sum((-1)**k*math.comb(int(p[0]),k)*(1-k/p[0])**p[1] for k in range(int(p[0])+1))))],'A toy collector draws {Draws} independent uniform coupons among {Types} types. What probability has it collected every type?','Inclusion-exclusion sums the missing-type events. A collection transition can illustrate concentration without proving cutoff for an arbitrary Markov chain.','grid')
op('latentinfo','Coupled Noise','MutualBits','[(()=>{if(![0,1].includes(p[0])||p[1]<=0||p[1]>=1)throw Error("Invalid binary channel");const h=-p[1]*Math.log2(p[1])-(1-p[1])*Math.log2(1-p[1]);return p[0]===1?1-h:0;})()]',lambda p:[1-(-p[1]*math.log2(p[1])-(1-p[1])*math.log2(1-p[1])) if p[0]==1 else 0],'A uniform binary toy code drives a noisy binary decoder with flip probability {Noise} when Coupled {Coupled}=1. At 0 the output is independent. What mutual information remains?','Ignoring a latent code removes information from that code to the output. This channel analogy does not reproduce VAE training dynamics.','grid')
